// Data peta: Natural Earth via paket `world-atlas` (domain publik).
// Cantumkan atribusi "Natural Earth" di credit akhir.
const topo = land_50m_namespaceObject;
const geo_projection = equalEarth().fitWidth(1080, {
    type: "Sphere"
});
const pathGen = src_path(geo_projection);
const LAND_D = pathGen(feature(topo, topo.objects.land)) ?? "";
const SPHERE_D = pathGen({
    type: "Sphere"
}) ?? "";
const geo_project = (lon, lat)=>{
    const p = geo_projection([
        lon,
        lat
    ]);
    return p ? [
        p[0],
        p[1]
    ] : [
        0,
        0
    ];
};
const TAMBORA = {
    lon: 118.0,
    lat: -8.25
}; // Smithsonian GVP: 8.25°S, 118°E
const SWISS = {
    lon: 8.2,
    lat: 46.8
};
const NEW_ENGLAND = {
    lon: -72.0,
    lat: 43.5
};
const toScreen = (v, lon, lat)=>{
    const [fx, fy] = geo_project(v.lon, v.lat);
    const [px, py] = geo_project(lon, lat);
    return [
        v.sx + v.k * (px - fx),
        v.sy + v.k * (py - fy)
    ];
};
// Interpolasi antar view; zoom pakai skala logaritmik supaya terasa halus.
const mixView = (a, b, t)=>({
        lon: a.lon + (b.lon - a.lon) * t,
        lat: a.lat + (b.lat - a.lat) * t,
        sx: a.sx + (b.sx - a.sx) * t,
        sy: a.sy + (b.sy - a.sy) * t,
        k: a.k * Math.pow(b.k / a.k, t)
    });
const WORLD_VIEW = {
    lon: 0,
    lat: 0,
    sx: 540,
    sy: 1000,
    k: 1.0
};
const SUMBAWA_VIEW = {
    lon: TAMBORA.lon,
    lat: TAMBORA.lat,
    sx: 540,
    sy: 900,
    k: 75
};

;// CONCATENATED MODULE: ./src/suhuf-tambora/theme.ts


